begin;
create table if not exists public.mme_inventory_locations(location_id uuid primary key default gen_random_uuid(),location_code text not null unique,location_name text not null,location_type text not null default 'store' check(location_type in('store','warehouse','stockroom','transit','vendor','quarantine')),address jsonb not null default '{}'::jsonb,active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.mme_inventory_vendors(vendor_id uuid primary key default gen_random_uuid(),vendor_name text not null,contact_email text,contact_phone text,account_reference text,active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.mme_inventory_skus(inventory_sku_id uuid primary key default gen_random_uuid(),sku text not null unique,catalog_product_id uuid,product_name text not null,brand text,category text,condition text not null default 'new' check(condition in('new','open_box','used','refurbished','parts')),unit_cost numeric(12,2) not null default 0 check(unit_cost>=0),retail_price numeric(12,2) check(retail_price is null or retail_price>=0),reorder_point integer not null default 0 check(reorder_point>=0),reorder_quantity integer not null default 0 check(reorder_quantity>=0),track_serial boolean not null default false,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.mme_inventory_balances(balance_id uuid primary key default gen_random_uuid(),inventory_sku_id uuid not null references public.mme_inventory_skus(inventory_sku_id),location_id uuid not null references public.mme_inventory_locations(location_id),on_hand integer not null default 0 check(on_hand>=0),reserved integer not null default 0 check(reserved>=0 and reserved<=on_hand),updated_at timestamptz not null default now(),unique(inventory_sku_id,location_id));
create table if not exists public.mme_inventory_serials(serial_id uuid primary key default gen_random_uuid(),inventory_sku_id uuid not null references public.mme_inventory_skus(inventory_sku_id),location_id uuid references public.mme_inventory_locations(location_id),serial_number text not null unique,imei text unique,asset_status text not null default 'available' check(asset_status in('available','reserved','sold','returned','quarantine','damaged','transit')),condition text not null,received_at timestamptz not null default now(),sold_at timestamptz,metadata jsonb not null default '{}'::jsonb);
create table if not exists public.mme_inventory_movements(movement_id uuid primary key default gen_random_uuid(),inventory_sku_id uuid not null references public.mme_inventory_skus(inventory_sku_id),from_location_id uuid references public.mme_inventory_locations(location_id),to_location_id uuid references public.mme_inventory_locations(location_id),quantity integer not null check(quantity>0),movement_type text not null check(movement_type in('receive','sale','return','transfer','adjustment','damage','reserve','release','count')),reference_type text,reference_id uuid,notes text,actor_auth_user_id uuid not null,created_at timestamptz not null default now());
create table if not exists public.mme_inventory_purchase_orders(purchase_order_id uuid primary key default gen_random_uuid(),po_number text not null unique,vendor_id uuid references public.mme_inventory_vendors(vendor_id),destination_location_id uuid not null references public.mme_inventory_locations(location_id),po_status text not null default 'draft' check(po_status in('draft','submitted','partially_received','received','cancelled')),expected_at date,total_cost numeric(14,2) not null default 0,created_by_auth_user_id uuid not null,created_at timestamptz not null default now());
create table if not exists public.mme_inventory_po_lines(po_line_id uuid primary key default gen_random_uuid(),purchase_order_id uuid not null references public.mme_inventory_purchase_orders(purchase_order_id),inventory_sku_id uuid not null references public.mme_inventory_skus(inventory_sku_id),ordered_quantity integer not null check(ordered_quantity>0),received_quantity integer not null default 0 check(received_quantity>=0 and received_quantity<=ordered_quantity),unit_cost numeric(12,2) not null check(unit_cost>=0),unique(purchase_order_id,inventory_sku_id));
create table if not exists public.mme_inventory_transfers(transfer_id uuid primary key default gen_random_uuid(),transfer_number text not null unique,from_location_id uuid not null references public.mme_inventory_locations(location_id),to_location_id uuid not null references public.mme_inventory_locations(location_id),transfer_status text not null default 'draft' check(transfer_status in('draft','in_transit','received','cancelled')),created_by_auth_user_id uuid not null,created_at timestamptz not null default now(),check(from_location_id<>to_location_id));
create table if not exists public.mme_inventory_transfer_lines(transfer_line_id uuid primary key default gen_random_uuid(),transfer_id uuid not null references public.mme_inventory_transfers(transfer_id),inventory_sku_id uuid not null references public.mme_inventory_skus(inventory_sku_id),quantity integer not null check(quantity>0),received_quantity integer not null default 0 check(received_quantity>=0 and received_quantity<=quantity));
create table if not exists public.mme_inventory_counts(count_id uuid primary key default gen_random_uuid(),location_id uuid not null references public.mme_inventory_locations(location_id),count_status text not null default 'open' check(count_status in('open','submitted','approved','rejected')),started_by_auth_user_id uuid not null,approved_by_auth_user_id uuid,created_at timestamptz not null default now(),completed_at timestamptz);
create table if not exists public.mme_inventory_count_lines(count_line_id uuid primary key default gen_random_uuid(),count_id uuid not null references public.mme_inventory_counts(count_id),inventory_sku_id uuid not null references public.mme_inventory_skus(inventory_sku_id),system_quantity integer not null check(system_quantity>=0),counted_quantity integer not null check(counted_quantity>=0),unique(count_id,inventory_sku_id));
create index if not exists mme_inventory_balance_location_idx on public.mme_inventory_balances(location_id,inventory_sku_id);
create index if not exists mme_inventory_movement_history_idx on public.mme_inventory_movements(inventory_sku_id,created_at desc);
create index if not exists mme_inventory_serial_imei_idx on public.mme_inventory_serials(imei) where imei is not null;
create or replace function public.mme_inventory_move(p_sku uuid,p_from uuid,p_to uuid,p_qty integer,p_type text,p_actor uuid,p_notes text default null,p_reference_type text default null,p_reference_id uuid default null)
returns uuid language plpgsql security definer set search_path=public as $$
declare movement uuid; source_qty integer;
begin
 if p_qty is null or p_qty<=0 then raise exception 'quantity_must_be_positive'; end if;
 if p_type not in('receive','sale','return','transfer','adjustment','damage','count') then raise exception 'invalid_movement_type'; end if;
 if p_from is not null then
  select on_hand into source_qty from public.mme_inventory_balances where inventory_sku_id=p_sku and location_id=p_from for update;
  if not found or source_qty<p_qty then raise exception 'insufficient_available_inventory'; end if;
  update public.mme_inventory_balances set on_hand=on_hand-p_qty,updated_at=now() where inventory_sku_id=p_sku and location_id=p_from;
 end if;
 if p_to is not null then
  insert into public.mme_inventory_balances(inventory_sku_id,location_id,on_hand) values(p_sku,p_to,p_qty)
  on conflict(inventory_sku_id,location_id) do update set on_hand=mme_inventory_balances.on_hand+excluded.on_hand,updated_at=now();
 end if;
 insert into public.mme_inventory_movements(inventory_sku_id,from_location_id,to_location_id,quantity,movement_type,reference_type,reference_id,notes,actor_auth_user_id)
 values(p_sku,p_from,p_to,p_qty,p_type,p_reference_type,p_reference_id,p_notes,p_actor) returning movement_id into movement;
 return movement;
end;$$;
revoke all on function public.mme_inventory_move(uuid,uuid,uuid,integer,text,uuid,text,text,uuid) from public,anon,authenticated;
grant execute on function public.mme_inventory_move(uuid,uuid,uuid,integer,text,uuid,text,text,uuid) to service_role;
do $$declare t text;begin foreach t in array array['mme_inventory_locations','mme_inventory_vendors','mme_inventory_skus','mme_inventory_balances','mme_inventory_serials','mme_inventory_movements','mme_inventory_purchase_orders','mme_inventory_po_lines','mme_inventory_transfers','mme_inventory_transfer_lines','mme_inventory_counts','mme_inventory_count_lines'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end$$;
commit;